/**
 * Fireworks shader.
 *
 * ## The mathematical idea
 *
 * A burst is a start point, an age and a seed. Each spark leaves it in a
 * direction spread around the circle, at a hashed speed, and its position
 * at instant t is analytic: the distance travelled under a drag
 * proportional to the speed is `v0 (1 - e^{-kt}) / k` — the sparks slow
 * down of their own accord — and gravity takes `g t^2 / 2` off the height.
 * Nothing is integrated from frame to frame: each fragment solves the spark
 * where it is.
 *
 * The fading out is an exponential of the age, modulated by a fast flicker
 * of its own phase; a brief flash at the start point marks the explosion
 * itself.
 *
 * The bursts live in a buffer of six slots timestamped by the engine clock
 * — a start at -1000 gives an enormous age, hence an inert burst — and an
 * automatic burst, drawn from a period counter, goes off on its own at a
 * hashed point: a sky that comes alive only on a click would stay empty on
 * most pages.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the sky.
 * - `uColorB`, `uColorC` — the two spark hues, mixed per burst.
 * - `uClicks` — six bursts (x, y, start time), circular buffer.
 * - `uSparks` — sparks per burst, and so the cost.
 * - `uGravity` — strength of the fall-back.
 * - `uDecay` — rate at which the sparks fade out.
 * - `uAuto` — period of the automatic bursts, in seconds; zero cuts them.
 */
export const FIREWORKS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform vec3 uClicks[6];
uniform float uSparks;
uniform float uGravity;
uniform float uDecay;
uniform float uAuto;

// Pseudo-random number: projection onto an arbitrary direction, amplified
// sine, fractional part.
float burstHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Two decorrelated numbers for the same seed.
vec2 burstHash2(vec2 p) {
  return vec2(burstHash(p), burstHash(p + vec2(37.3, 17.7)));
}

// Light a burst lays down at point p, at the given age.
vec3 burst(vec2 p, vec2 origin, float age, float seed, int sparks) {
  // Too early or too old: nothing to compute, and that is the case for every
  // empty slot of the buffer.
  if (age < 0.0 || age > 6.0) return vec3(0.0);

  vec3 light = vec3(0.0);
  float burstTint = burstHash(vec2(seed, 3.1));
  float k = 1.6;

  // Constant bounds: the language specification demands it; quality exits
  // earlier.
  for (int j = 0; j < 48; j += 1) {
    if (j >= sparks) break;
    float fj = float(j);
    vec2 h = burstHash2(vec2(fj, seed));

    // Directions spread around the circle, each nudged a little: a regular
    // burst looks mechanical, a random burst has holes.
    float angle = (fj + h.x * 0.8) / float(sparks) * 6.28318;
    float v0 = 0.22 + 0.25 * h.y;

    float reach = v0 * (1.0 - exp(-k * age)) / k;
    vec2 pos = origin + vec2(cos(angle), sin(angle)) * reach;
    pos.y -= uGravity * age * age * 0.5;

    float d = length(p - pos);
    float size = 0.006 + 0.004 * h.y;
    float core = exp(-d * d / (size * size));
    float halo = 0.15 * exp(-d * d / (size * size * 12.0));

    float decay = exp(-uDecay * age) * (0.75 + 0.25 * sin(age * 25.0 + h.x * 6.28318));
    decay *= smoothstep(0.0, 0.05, age);

    vec3 tint = mix(uColorB, uColorC, fract(burstTint + h.y * 0.35));
    light += tint * (core + halo) * decay;
  }

  // The flash of the explosion: broad, brief, at the start point.
  float d0 = length(p - origin);
  light += uColorC * exp(-d0 * d0 / 0.002) * exp(-age * 12.0) * 2.0;

  return light;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0);
  int sparks = int(clamp(uSparks, 4.0, 48.0));

  vec3 colour = uColorA;

  for (int i = 0; i < 6; i += 1) {
    vec3 click = uClicks[i];
    vec2 origin = click.xy * vec2(aspect, 1.0);
    colour += burst(p, origin, uTime - click.z, click.z * 7.3 + float(i), sparks);
  }

  // The automatic burst: one per period, at a hashed point of the frame's top.
  if (uAuto > 0.0) {
    float period = max(uAuto, 0.5);
    float index = floor(uTime / period);
    float autoAge = uTime - index * period;
    vec2 autoOrigin = vec2(0.2 + 0.6 * burstHash(vec2(index, 1.3)), 0.45 + 0.4 * burstHash(vec2(index, 9.1)));
    colour += burst(p, autoOrigin * vec2(aspect, 1.0), autoAge, index * 3.7, sparks);
  }

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Fireworks: a burst breaks open at every click and falls back under
 * gravity.
 *
 * ## What this background reacts to
 *
 * On a click — or a touch — on the frame: each press timestamps a burst in
 * a circular buffer of six slots, and the sparks leave from the exact point
 * of the press. Moving the pointer changes nothing.
 *
 * An automatic burst also goes off on its own, at a set interval: a sky
 * that exists only on a click would stay empty on most pages. Zero cuts
 * it.
 *
 * ## The click -> shader bridge
 *
 * No React render per frame: the buffer is a stable array of eighteen
 * floats (six times x, y, start time), mutated in place on every click.
 * The surface re-reads its uniforms every frame, the array's identity never
 * changes — mutating is enough.
 *
 * The time written into the buffer is the engine clock's, recorded by a
 * subscription at input priority: it is the same time as the shader's `uTime`,
 * without which the age of the bursts would be wrong.
 *
 * ## Under reduced motion
 *
 * The surface is refused by the engine and the static fallback shows.
 *
 * @module
 */

import {
  CLOCK_PRIORITY,
  clock,
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { useEffect, useRef, useState, type ReactElement } from 'react'

import { FIREWORKS_FRAGMENT } from './fireworks.shader.js'

/** What the escape hatch receives. */
export interface FireworksControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Properties specific to this component. */
export interface FireworksOwnProps {
  /** Sparks per burst. @defaultValue 32 */
  sparks?: number
  /** Strength of the fall-back. @defaultValue 0.25 */
  gravity?: number
  /** Rate at which the sparks fade out. @defaultValue 1.1 */
  decay?: number
  /** Period of the automatic bursts, in seconds. Zero cuts them. @defaultValue 2.6 */
  auto?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<FireworksControls>
}

/** Every property. */
export type FireworksProps = Customisable<FireworksOwnProps>

/** Tokens used by default: the sky, the two spark hues. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-brand-500',
  '--o-palette-amber-200',
] as const

/** Default fallback: a frozen sky, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-t o-from-zinc-50 dark:o-from-zinc-950 o-to-brand-200 dark:o-to-brand-950'

/** Number of bursts live at once. */
const SLOTS = 6

/**
 * Sparks per burst at low quality.
 *
 * Each spark is an exponential and a sine per fragment, for each of the
 * seven possible bursts: it is the only lever on cost, and it does not need
 * to be a prop in order to be degraded.
 */
const LOW_SPARKS = 14

/**
 * Fireworks.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Fireworks className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Fireworks({
  sparks = 32,
  gravity = 0.25,
  decay = 1.1,
  auto = 2.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: FireworksProps): ReactElement {
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  // Stable buffer, mutated in place: six times (x, y, start time). A start
  // at -1000 gives an enormous age, hence a burst inert by default.
  const uClicks = useRef<number[]>(Array.from({ length: SLOTS * 3 }, () => -1000)).current

  // The engine clock's time — the same as the shader's uTime. It is what
  // timestamps the bursts; performance.now() would give another origin.
  const lastTime = useRef(0)

  useEffect(() => {
    const subscription = clock.subscribe(
      ({ time }) => {
        lastTime.current = time
      },
      { priority: CLOCK_PRIORITY.input, name: 'fireworks : clock' },
    )
    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (host === null) return

    const onDown = (event: PointerEvent): void => {
      const bounds = host.getBoundingClientRect()
      const x = (event.clientX - bounds.left) / Math.max(bounds.width, 1)
      // vUv has its origin at the bottom: the screen's vertical axis is flipped.
      const y = 1 - (event.clientY - bounds.top) / Math.max(bounds.height, 1)

      // Circular buffer: everything shifts by one, the new burst at the head.
      for (let i = SLOTS - 1; i > 0; i -= 1) {
        uClicks[i * 3] = uClicks[(i - 1) * 3] ?? -1000
        uClicks[i * 3 + 1] = uClicks[(i - 1) * 3 + 1] ?? -1000
        uClicks[i * 3 + 2] = uClicks[(i - 1) * 3 + 2] ?? -1000
      }
      uClicks[0] = x
      uClicks[1] = y
      uClicks[2] = lastTime.current
    }

    host.addEventListener('pointerdown', onDown)
    return () => host.removeEventListener('pointerdown', onDown)
  }, [host, uClicks])

  const {
    ref,
    setHost: setShaderHost,
    ready,
    refused,
    colours,
  } = useTokenShader<HTMLDivElement>({
    fragment: FIREWORKS_FRAGMENT,
    colors,
    uniforms: {
      uClicks,
      uSparks: sparks,
      uGravity: gravity,
      uDecay: decay,
      uAuto: auto,
    },
    name: 'fireworks',
    degrade: (quality) => ({
      uSparks: quality === 'low' ? Math.min(sparks, LOW_SPARKS) : sparks,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        setShaderHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
